// Функция для проверки и очистки Date_Unblock
function checkDateUnblock() {
    // Получаем текущие дату и время
    var currentDate = new Date();
    console.log("Текущая дата и время: " + currentDate);

    // Получаем значение переменной Date_Unblock
    var dateUnblockStr = player.GetVar("Date_Unblock");
    console.log("Значение Date_Unblock: " + dateUnblockStr);

    // Проверяем значение переменной Date_Unblock
    if (dateUnblockStr && dateUnblockStr !== "0") {
        try {
            // Преобразуем значение переменной Date_Unblock в объект Date
            var dateParts = dateUnblockStr.split(" ");
            var datePart = dateParts[0].split(":");
            var timePart = dateParts[1].split(":");

            var unblockDate = new Date(
                parseInt(datePart[2], 10),    // Год
                parseInt(datePart[1], 10) - 1, // Месяц (нумерация с 0)
                parseInt(datePart[0], 10),    // День
                parseInt(timePart[0], 10),    // Часы
                parseInt(timePart[1], 10),    // Минуты
                parseInt(timePart[2], 10)     // Секунды
            );
            console.log("Преобразованная дата и время Date_Unblock: " + unblockDate);

            // Сравниваем текущие дату и время с Date_Unblock
            if (currentDate > unblockDate) {
                console.log("Переходим к титульному слайду."); 
                // Присваиваем переменной FinalView значение "200"
                player.SetVar("FinalView", "200"); 
            } else {
                console.log("Текущая дата и время не позже Date_Unblock.");
            }
        } catch (error) {
            console.log("Ошибка при преобразовании Date_Unblock: " + error);
            player.SetVar("FinalView", "200"); // Переходим к титульному слайду в случае ошибки преобразования
        }
    } else {
        console.log("Date_Unblock пустое, равно нулю или не определено.");
        player.SetVar("FinalView", "200"); // Переходим к титульному слайду
    }
}

// Выполняем проверку сразу при запуске скрипта
checkDateUnblock();

function calculateCompanyScore(config) {
    // Получаем объект Player
    var player = GetPlayer();

    // Получаем значения переменных
    var ktData = player.GetVar(config.ktVarName);
    var variant = player.GetVar(config.variantVarName);
    console.log(`${config.ktVarName}:`, ktData); // Отладка
    console.log(`${config.variantVarName}:`, variant); // Отладка

    // Проверяем, получены ли корректные значения переменных
    if (ktData && typeof ktData === 'string' && variant) {
        // Преобразуем строку в массив
        var ktArray = ktData.slice(1, -1).split('],[').map(function(item) {
            return item ? item.split(',') : [];
        });

        console.log('KT Array:', ktArray); // Отладка

        // Правильные ответы для ячеек в зависимости от значения Variant
        var correctAnswers = config.correctAnswers[variant - 1];
        if (!correctAnswers) {
            console.error('Неверное значение Variant.');
            return;
        }

        // Переменные для хранения баллов каждой ячейки
        var scores = new Array(correctAnswers.length).fill(0);

        // Функция для проверки правильности ответов и подсчета баллов для ячеек с одним верным ответом
        function calculateSingleAnswerScore(cellAnswers, correctAnswer) {
            if (cellAnswers.length === 0) return 0; // Обработка пустой ячейки
            if (cellAnswers.length === 1 && cellAnswers[0] === correctAnswer) {
                return 1;
            }
            return 0;
        }

        // Функция для проверки правильности ответов и подсчета баллов для ячеек с двумя верными ответами
        function calculateMultipleAnswerScore(cellAnswers, correctAnswers) {
            if (cellAnswers.length === 0) return 0; // Обработка пустой ячейки

            var correctCount = 0;
            var incorrectCount = 0;
            var seenAnswers = [];

            // Разбиваем каждый элемент на отдельные символы
            cellAnswers.forEach(function(answer) {
                answer.split('').forEach(function(char) {
                    if (correctAnswers.includes(char)) {
                        if (!seenAnswers.includes(char)) {
                            correctCount++;
                            seenAnswers.push(char);
                        }
                    } else {
                        incorrectCount++;
                    }
                });
            });

            // Рассчитываем баллы по правилам
            if (correctCount === 2 && incorrectCount === 0) return 2;
            if (correctCount === 1 && incorrectCount === 0) return 1; // 1 балл за один правильный символ
            if (correctCount === 1 && incorrectCount === 1) return 1;
            if (correctCount === 2 && incorrectCount === 1) return 1;
            return 0;
        }

        // Функция для проверки правильности ответов и подсчета баллов для ячеек с несколькими символами
        function calculateComplexAnswerScore(cellAnswers, correctAnswer) {
            if (cellAnswers.length === 0) return 0; // Обработка пустой ячейки

            if (cellAnswers.length === 1) {
                if (cellAnswers[0] === correctAnswer) return 3;

                var pairs = ["A1", "B2", "C3", "D4"];
                var correctPairs = 0;
                pairs.forEach(function(pair) {
                    if (cellAnswers[0].includes(pair)) {
                        correctPairs++;
                    }
                });

                if (correctPairs === 4) return 3;
                if (correctPairs >= 2) return 2;
                if (correctPairs === 1) return 1;
            }
            return 0;
        }

        // Рассчитываем баллы для каждой ячейки, начиная с начальной ячейки
        for (var i = config.startCell - 1; i < correctAnswers.length + config.startCell - 1; i++) {
            var answers = ktArray[i] || [];
            console.log(`Answers for cell ${i + 1}:`, answers); // Отладка

            var correctAnswer = correctAnswers[i - (config.startCell - 1)];
            var score;

            if (correctAnswer.length === 1 && correctAnswer[0].length > 1) {
                score = calculateComplexAnswerScore(answers, correctAnswer[0]);
            } else if (correctAnswer.length === 1) {
                score = calculateSingleAnswerScore(answers, correctAnswer[0]);
            } else {
                score = calculateMultipleAnswerScore(answers, correctAnswer);
            }

            scores[i - (config.startCell - 1)] = score;
        }

        // Суммируем все баллы
        var totalScore = scores.reduce((a, b) => a + b, 0);

        // Отладочные сообщения
        console.log('Scores:', {
            scores: scores,
            totalScore: totalScore
        });

        // Устанавливаем итоговый балл в переменную resultVarName
        player.SetVar(config.resultVarName, totalScore);
    } else {
        console.error(`Переменная ${config.ktVarName} не получена или имеет неверный формат.`);
    }
}

