// Определяем функцию для обработки переменных
function calculateSumAndSetVar(textVarName, numVarName) {
    var player = GetPlayer();
    var textVar = player.GetVar(textVarName);

    // Инициализируем переменную для хранения суммы
    var sum = 0;

    // Проходим по каждому символу строки и добавляем его значение к сумме
    for (var i = 0; i < textVar.length; i++) {
        sum += parseInt(textVar.charAt(i), 10);
    }

    // Устанавливаем значение числовой переменной
    player.SetVar(numVarName, sum);
}

// Вызов функции с нужными аргументами
calculateSumAndSetVar("CT_team_management", "Check_team_management");
calculateSumAndSetVar("CT_critical_thinking", "Check_critical_thinking");
calculateSumAndSetVar("CT_change_management", "Check_change_management");
calculateSumAndSetVar("CT_clientcentrity", "Check_clientcentrity");

// Проверка и установка значений на основе Variant_1 и Variant_2
function checkAndSetResults() {
    var player = GetPlayer();

    // Получение значений Variant_1 и Variant_2
    var variant1 = player.GetVar("Variant_1");
    var variant2 = player.GetVar("Variant_2");

    // Получение значений Check переменных
    var checkCriticalThinking = player.GetVar("Check_critical_thinking");
    var checkTeamManagement = player.GetVar("Check_team_management");
    var checkChangeManagement = player.GetVar("Check_change_management");
    var checkClientCentrity = player.GetVar("Check_clientcentrity");

    // Логика проверки для Variant_1
    if (variant1 == 1 || variant1 == 3) {
        player.SetVar("Result_Crirical_Thinking", checkCriticalThinking > 4);
        player.SetVar("Result_Team_Management", checkTeamManagement > 4);
    } else if (variant1 == 2 || variant1 == 4) {
        player.SetVar("Result_Crirical_Thinking", checkCriticalThinking > 3);
        player.SetVar("Result_Team_Management", checkTeamManagement > 4);
    }

    // Логика проверки для Variant_2
    if (variant2 == 1 || variant2 == 3) {
        player.SetVar("Result_Change_Management", checkChangeManagement > 4);
        player.SetVar("Result_Client", checkClientCentrity > 4);
    } else if (variant2 == 2 || variant2 == 4) {
        player.SetVar("Result_Change_Management", checkChangeManagement > 5);
        player.SetVar("Result_Client", checkClientCentrity > 4);
    }
}

// Вызов функции проверки и установки результатов
checkAndSetResults();

// Функция для вычисления итогового балла и обновления булевой переменной Result_Tech
function calculateFinalScoreAndSetResult() {
    // Получаем объект Player
    var player = GetPlayer();

    // Получаем значения переменных
    var variant3 = player.GetVar("Variant_3");
    var checkTechnology = player.GetVar("Check_Technology");
    var checkTechnology2 = player.GetVar("Check_Technology_2");

    // Складываем Check_Technology и Check_Technology_2, чтобы получить сумму баллов
    var totalScore = checkTechnology + checkTechnology2;
    var finalScore = totalScore;

    // Выполняем дополнительные вычисления в зависимости от значения Variant_3
    if (variant3 === 1) {
        finalScore = (1.27 * totalScore) - 5.15;
    } else if (variant3 === 2) {
        finalScore = (1.15 * totalScore) - 0.61;
    }

    // Проверяем, если итоговое значение >= 10, то Result_Tech = True, иначе False
    var resultTech = finalScore >= 10;
    
    // Обновляем значение переменной Result_Tech
    player.SetVar("Result_Tech", resultTech);

    // Отладочные сообщения
    console.log('Variant_3:', variant3);
    console.log('Check_Technology:', checkTechnology);
    console.log('Check_Technology_2:', checkTechnology2);
    console.log('Total Score:', totalScore);
    console.log('Final Score:', finalScore);
    console.log('Result_Tech:', resultTech);
}

// Пример вызова функции
calculateFinalScoreAndSetResult();

function calculateFinalScoreAndSetResult(settings) {
    // Получаем объект Player
    var player = GetPlayer();

    // Получаем значения переменных из объекта settings
    var variantKey = settings.variantKey || "Variant_3";
    var checkTechKey = settings.checkTechKey || "Check_Technology";
    var checkTech2Key = settings.checkTech2Key || "Check_Technology_2";
    var checkTech3Key = settings.checkTech3Key || "Check_Technology_3";
    var resultTechKey = settings.resultTechKey || "Result_Tech";
    var variant = player.GetVar(variantKey);
    var checkTechnology = player.GetVar(checkTechKey);
    var checkTechnology2 = player.GetVar(checkTech2Key);
    var checkTechnology3 = player.GetVar(checkTech3Key);

    // Складываем значения переменных, чтобы получить сумму баллов
    var totalScore = checkTechnology + checkTechnology2 + checkTechnology3;
    var finalScore = totalScore;

    // Выполняем дополнительные вычисления в зависимости от значения variant
    if (variant === 1) {
        finalScore = (settings.variant1Factor * totalScore) + settings.variant1Offset;
    } else if (variant === 2) {
        finalScore = (settings.variant2Factor * totalScore) + settings.variant2Offset;
    }

    // Проверяем, если итоговое значение >= settings.threshold, то resultTech = True, иначе False
    var resultTech = finalScore >= settings.threshold;
    
    // Обновляем значение переменной resultTechKey
    player.SetVar(resultTechKey, resultTech);

    // Отладочные сообщения
    console.log(variantKey + ':', variant);
    console.log(checkTechKey + ':', checkTechnology);
    console.log(checkTech2Key + ':', checkTechnology2);
    console.log(checkTech3Key + ':', checkTechnology3);
    console.log('Total Score:', totalScore);
    console.log('Final Score:', finalScore);
    console.log(resultTechKey + ':', resultTech);
}

// Пример вызова функции с настройками
