// === Функция показа оверлея с крутящимися часиками ===
function showOverlay(message) {
    var overlay = document.createElement('div');
    overlay.id = 'pdf-overlay';
    overlay.style.cssText = [
        'position:fixed', 'top:0', 'left:0', 'width:100%', 'height:100%',
        'background:rgba(0,0,0,0.6)', 'z-index:99999',
        'display:flex', 'flex-direction:column',
        'align-items:center', 'justify-content:center',
        'color:white', 'font-family:Arial,sans-serif', 'font-size:18px'
    ].join(';');
    overlay.innerHTML = [
        '<div style="border:5px solid #fff;border-top-color:transparent;',
        'border-radius:50%;width:50px;height:50px;',
        'animation:spin 1s linear infinite;margin-bottom:20px"></div>',
        '<div>' + message + '</div>',
        '<style>@keyframes spin{to{transform:rotate(360deg)}}</style>'
    ].join('');
    document.body.appendChild(overlay);
}

// === Функция скрытия оверлея ===
function hideOverlay() {
    var overlay = document.getElementById('pdf-overlay');
    if (overlay) overlay.parentNode.removeChild(overlay);
}

// === Функция показа ошибки в оверлее ===
function showError(message) {
    var overlay = document.getElementById('pdf-overlay');
    if (overlay) {
        overlay.innerHTML = [
            '<div style="font-size:40px;margin-bottom:20px">⚠️</div>',
            '<div style="text-align:center;padding:0 20px">' + message + '</div>',
            '<button onclick="document.body.removeChild(document.getElementById(\'pdf-overlay\'))" ',
            'style="margin-top:20px;padding:10px 24px;background:#e05c2a;border:none;',
            'border-radius:6px;color:white;font-size:16px;cursor:pointer">Закрыть</button>'
        ].join('');
    }
}

// Имя файла отчета
var certFilename = 'report.html';

// Коллекция элементов типа iFrame
var iframeElements = document.getElementsByTagName("iframe");

// Флаг - нашли ли нужный iFrame
var found = false;

// Показываем оверлей сразу при нажатии кнопки
showOverlay('Идёт создание отчёта...');

// Проходимся по коллекции элементов iFrame
for (var i = 0; i < iframeElements.length; i++) {
    // Получаем атрибут src текущего элемента iFrame
    var src = iframeElements[i].getAttribute('src');
    console.log('Проверка iFrame с src: ' + src); // Отладочная информация
    if (src && src.indexOf(certFilename) !== -1) {
        console.log('Найден iFrame с соответствующим src.'); // Отладочная информация

        // Ставим флаг что нашли нужный iFrame
        found = true;

        // Пытаемся вызвать функцию generatePDF в контексте найденного iFrame
        try {
            if (iframeElements[i].contentWindow.generatePDF) {
                iframeElements[i].contentWindow.generatePDF();
                console.log('Функция generatePDF вызвана успешно.'); // Отладочная информация
                // Скрываем оверлей через 3 секунды - PDF уже начал скачиваться
                setTimeout(hideOverlay, 3000);
            } else {
                console.error('Функция generatePDF не найдена в контексте iframe.'); // Отладочная информация
                // Показываем сообщение об ошибке пользователю
                showError('Не удалось создать отчёт. Попробуй нажать «Скачать отчёт» ещё раз.');
            }
        } catch (e) {
            console.error('Ошибка при вызове generatePDF: ', e); // Отладочная информация
            // Показываем сообщение об ошибке пользователю
            showError('Не удалось создать отчёт. Попробуй нажать «Скачать отчёт» ещё раз.');
        }

        // Прерываем цикл - нужный iFrame уже найден
        break;
    }
}

// Если iFrame с report.html не найден вообще - показываем ошибку
if (!found) {
    showError('Не удалось создать отчёт. Попробуй нажать «Скачать отчёт» ещё раз.');
}

