var currentDate = new Date();

// Преобразуем текущую дату в формат ДД.ММ.ГГГГ
var day = currentDate.getDate();
var month = currentDate.getMonth() + 1; // Месяцы в JavaScript начинаются с 0
var year = currentDate.getFullYear();

// Форматируем день и месяц с ведущим нулем
day = day < 10 ? '0' + day : day;
month = month < 10 ? '0' + month : month;

// Создаем строку в формате ДД.ММ.ГГГГ
var formattedDateFinished = day + "." + month + "." + year;

// Устанавливаем значение переменной DateFinished
player.SetVar("DateFinished", formattedDateFinished);

// Добавляем 14 дней к текущему времени
var futureDate = new Date(currentDate.getTime() + 14 * 24 * 60 * 60 * 1000);

// Преобразуем дату в формат ДД:ММ:ГГГГ
day = futureDate.getDate();
month = futureDate.getMonth() + 1;
year = futureDate.getFullYear();

// Форматируем день и месяц с ведущим нулем
day = day < 10 ? '0' + day : day;
month = month < 10 ? '0' + month : month;

// Преобразуем время в формат ЧЧ:ММ:СС
var hours = futureDate.getHours();
var minutes = futureDate.getMinutes();
var seconds = futureDate.getSeconds();

// Форматируем часы, минуты и секунды с ведущим нулем
hours = hours < 10 ? '0' + hours : hours;
minutes = minutes < 10 ? '0' + minutes : minutes;
seconds = seconds < 10 ? '0' + seconds : seconds;

// Создаем строку в формате ДД:ММ:ГГГГ ЧЧ:ММ:СС
var formattedDateUnblock = day + ":" + month + ":" + year + " " + hours + ":" + minutes + ":" + seconds;

// Устанавливаем значение переменной Date_Unblock
player.SetVar("Date_Unblock", formattedDateUnblock);

var player = GetPlayer();

// Получаем значение переменной Date_Unblock
var dateUnblock = player.GetVar("Date_Unblock");

// Обрезаем строку до формата ДД.ММ.ГГГГ
var formattedDateUnblock = dateUnblock.split(" ")[0].replace(/:/g, ".");

// Устанавливаем новое значение переменной Date_Unblock
player.SetVar("Date_Unblock_shown", formattedDateUnblock);
